**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
using namespace std;

bool jestCyfra(char c) { return c >= '0' && c <= '9'; }

int main() {
    ifstream plik("napisy.txt");
    string s;
    string maxNapis;
    int maxFragm = 0;
    while (plik >> s) {
        cout << s << ": ";
        int lit = 0, cyf = 0;
        int i = 0;
        bool first = true;
        while (i < (int)s.length()) {
            int j = i;
            if (jestCyfra(s[i])) {
                while (j < (int)s.length() && jestCyfra(s[j])) j++;
                cyf++;
            } else {
                while (j < (int)s.length() && !jestCyfra(s[j])) j++;
                lit++;
            }
            if (!first) cout << " ";
            first = false;
            cout << "[" << s.substr(i, j - i) << "]";
            i = j;
        }
        int total = lit + cyf;
        cout << " -> " << lit << " literowe, " << cyf << " cyfrowe" << endl;
        if (total > maxFragm) {
            maxFragm = total;
            maxNapis = s;
        }
    }
    cout << "Napis z najwieksza liczba fragmentow: " << maxNapis << " (" << maxFragm << ")" << endl;
    return 0;
}
```

**Wyjasnienie**: Algorytm "two-pointer": i to poczatek biezacego fragmentu, j przesuwa sie dopoki typ znaku jest taki sam. Fragment = `s.substr(i, j-i)`.

Weryfikacja:
- abc123def456: [abc][123][def][456] -> 2 lit, 2 cyf, total 4
- a1b2c3: [a][1][b][2][c][3] -> 3 lit, 3 cyf, total 6
- hello: [hello] -> 1 lit, 0 cyf, total 1
- 12345: [12345] -> 0 lit, 1 cyf, total 1
- kod2024matura: [kod][2024][matura] -> 2 lit, 1 cyf, total 3
- x9y8z7w6: [x][9][y][8][z][7][w][6] -> 4 lit, 4 cyf, total 8
- pro100gramy200: [pro][100][gramy][200] -> 2 lit, 2 cyf, total 4
- test: [test] -> 1 lit, 0 cyf, total 1
Max: x9y8z7w6 (8)
